using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Globalization;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps.EditorTools;
public static class Grounded180Checks {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static string phase;static string Out=>Path.Combine(Root,"Evidence180-"+phase);
 [Serializable]public class Row {public string kind;public bool liveExpected,prefabExpected,sceneExpected,oneMaterial,noColliders,poseMeshStable,noDoubleTint;public int instances,meshes;public float maxPrefabColourError,maxSceneColourError;public float[] liveTint;public string[] imageNames;}
 [Serializable]public class Report {public bool pass,regressionPassed,lossReproduced;public string phase;public Row[] rows;public string[] limits;}
 static void Check(bool b,string s){if(!b)throw new Exception(s);}static Vector3 V(float[] a)=>new Vector3(a[0],a[1],a[2]);
 static void Empty(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=Color.black;RenderSettings.ambientIntensity=0;RenderSettings.skybox=null;RenderSettings.reflectionIntensity=0;}
 static string Input(string kind){string dir=Path.Combine(Root,"Input180-"+kind);Directory.CreateDirectory(dir);var d=JsonUtility.FromJson<GroundedPropsV1.Data>(File.ReadAllText(Path.Combine(Root,"Input119/grounded_props.json")));var original=d.instances[0];var list=new List<GroundedPropsV1.Instance>();
  for(int k=0;k<3;k++){var i=JsonUtility.FromJson<GroundedPropsV1.Instance>(JsonUtility.ToJson(original));i.instanceId="tint180_"+k;float dx=k*.9f;i.source.position[0]+=dx;foreach(var p in i.parts)p.position[0]+=dx;i.tint=k==0?original.tint:k==1?new[]{.55f,.82f,.90f}:new[]{1f,1f,1f};list.Add(i);}d.instances=list.ToArray();if(kind=="legacy")foreach(var a in d.assets)a.surface=null;if(kind=="badPNG")foreach(var a in d.assets)a.surface.png="bad";
  File.WriteAllText(Path.Combine(dir,"grounded_props.json"),JsonUtility.ToJson(d));string fmt(float f)=>f.ToString("R",CultureInfo.InvariantCulture);File.WriteAllLines(Path.Combine(dir,"props.csv"),d.instances.Select(i=>string.Join(",",new[]{i.instanceId,"shells","tdj/shells",fmt(i.source.position[0]),fmt(i.source.position[1]),fmt(i.source.position[2]),fmt(i.source.yaw),fmt(i.source.scale[0]),fmt(i.source.scale[1]),"0","0"})));return dir;
 }
 static Color[] Expected(GroundedPropsV1.Data d,int i){var a=d.assets.Single(x=>x.id=="shells");var tint=d.instances[i].tint;var tc=new Color(tint[0],tint[1],tint[2],1);if(QualitySettings.activeColorSpace==ColorSpace.Linear)tc=tc.linear;tint=new[]{tc.r,tc.g,tc.b};return d.instances[i].parts.SelectMany(p=>{var part=a.parts.Single(x=>x.id==p.id);return Enumerable.Range(0,part.colors.Length/3).Select(k=>new Color(part.colors[k*3]*tint[0],part.colors[k*3+1]*tint[1],part.colors[k*3+2]*tint[2],1));}).ToArray();}
 static float Error(GameObject root,GroundedPropsV1.Data d){float error=0;for(int i=0;i<d.instances.Length;i++){var o=root.transform.Find(d.instances[i].instanceId).gameObject;var renderer=o.GetComponent<Renderer>();var pb=new MaterialPropertyBlock();renderer.GetPropertyBlock(pb);var tint=pb.isEmpty?renderer.sharedMaterial.GetColor("_BaseColor"):pb.GetColor("_BaseColor");if(!pb.isEmpty&&QualitySettings.activeColorSpace==ColorSpace.Linear)tint=tint.linear;var colours=o.GetComponent<MeshFilter>().sharedMesh.colors;var want=Expected(d,i);Check(colours.Length==want.Length,"colour count");for(int j=0;j<colours.Length;j++){var c=colours[j]*tint;error=Mathf.Max(error,Mathf.Abs(c.r-want[j].r),Mathf.Abs(c.g-want[j].g),Mathf.Abs(c.b-want[j].b));}}return error;}
 static string MeshShape(Mesh m){return JsonUtility.ToJson(new MeshData{p=m.vertices,n=m.normals,uv=m.uv,tri=m.triangles});}[Serializable]class MeshData{public Vector3[] p,n;public Vector2[] uv;public int[] tri;}
 static Camera Setup(GameObject root){var bounds=root.GetComponentInChildren<Renderer>().bounds;foreach(var r in root.GetComponentsInChildren<Renderer>())bounds.Encapsulate(r.bounds);var cam=new GameObject("tint180-camera").AddComponent<Camera>();cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.black;cam.aspect=4f/3;cam.fieldOfView=38;cam.transform.position=bounds.center+new Vector3(.1f,2.1f,-2.8f);cam.transform.LookAt(bounds.center);cam.GetUniversalAdditionalCameraData().renderPostProcessing=false;var sun=new GameObject("tint180-main").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1;sun.transform.rotation=Quaternion.Euler(45,30,0);var point=new GameObject("tint180-point").AddComponent<Light>();point.type=LightType.Point;point.color=new Color(1,.65f,.3f);point.intensity=6;point.range=8;point.transform.position=bounds.center+new Vector3(-.5f,1,-.4f);return cam;}
 static string[] Shots(string kind,string stage){var names=new List<string>();var cam=GameObject.Find("tint180-camera").GetComponent<Camera>();var sun=GameObject.Find("tint180-main").GetComponent<Light>();var point=GameObject.Find("tint180-point").GetComponent<Light>();foreach(string light in new[]{"main","point","spot","off"}){sun.enabled=light=="main";point.enabled=light=="point"||light=="spot";point.type=light=="spot"?LightType.Spot:LightType.Point;point.spotAngle=100;point.innerSpotAngle=65;point.transform.LookAt(GameObject.Find("tint180-root").GetComponentInChildren<Renderer>().bounds.center);RenderSettings.ambientLight=light=="main"?new Color(.15f,.15f,.15f):Color.black;RenderSettings.ambientIntensity=light=="main"?1:0;var im=Shared117Review.Image(cam,800,600);var name=kind+"-"+stage+"-"+light+".png";File.WriteAllBytes(Path.Combine(Out,name),im.EncodeToPNG());UnityEngine.Object.DestroyImmediate(im);names.Add(name);}return names.ToArray();}
 public static void RunBaseline(){Run("before3");}public static void RunFixed(){Run("after2");}
 static void Run(string p){phase=p;Directory.CreateDirectory(Out);try{var rp=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset");GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;var rows=new List<Row>();foreach(var kind in new[]{"textured","legacy","badPNG"}){
  Empty();var input=Input(kind);var data=GroundedPropsV1.Read(Path.Combine(input,"grounded_props.json"));var name="Grounded180-"+phase+"-"+kind;var folder="Assets/"+name;Check(!AssetDatabase.IsValidFolder(folder),"fresh output required "+folder);AssetDatabase.CreateFolder("Assets",name);var root=new GameObject("tint180-root");Check(GroundedPropsV1.Build(input,folder,root.transform,Shader.Find("MapSharedProps/Lit"))==3,"three built");var rs=root.GetComponentsInChildren<Renderer>();var ms=root.GetComponentsInChildren<MeshFilter>();var shapes=ms.Select(m=>MeshShape(m.sharedMesh)).ToArray();var poses=ms.Select(m=>m.transform.localToWorldMatrix).ToArray();if(phase.StartsWith("after")){for(int k=0;k<ms.Length;k++){var oldMesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Grounded180-before3-"+kind+"/grounded-placed-"+k.ToString("D4")+".asset");Check(oldMesh&&MeshShape(oldMesh)==MeshShape(ms[k].sharedMesh),"geometry normals UV unchanged from before");}foreach(var renderer in rs){var block=new MaterialPropertyBlock();renderer.GetPropertyBlock(block);Check(block.isEmpty,"no live tint double multiplication");}}bool one=rs.Select(r=>r.sharedMaterial).Distinct().Count()==1;Check(one,"shared material");Check(rs[0].sharedMaterial.GetColor("_BaseColor")==Color.white&&rs[0].sharedMaterial.IsKeywordEnabled("SMALL_PROP_LOCAL_LIGHTS"),"white shared/local lights");if(kind!="textured")Check((rs[0].sharedMaterial.GetTexture("_BaseMap")==null||rs[0].sharedMaterial.GetTexture("_BaseMap")==Texture2D.whiteTexture),"texture fallback");float liveError=Error(root,data);Check(liveError<.000002f,"live expected");Setup(root);var images=new List<string>();images.AddRange(Shots(kind,"live"));var prefabPath=folder+"/cluster.prefab";PrefabUtility.SaveAsPrefabAsset(root,prefabPath);AssetDatabase.SaveAssets();UnityEngine.Object.DestroyImmediate(root);root=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath));root.name="tint180-root";float prefabError=Error(root,data);images.AddRange(Shots(kind,"prefab"));var scene=folder+"/reload.unity";EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),scene);Empty();EditorSceneManager.OpenScene(scene);root=GameObject.Find("tint180-root");float sceneError=Error(root,data);images.AddRange(Shots(kind,"scene"));var current=root.GetComponentsInChildren<MeshFilter>();bool stable=current.Select(m=>MeshShape(m.sharedMesh)).SequenceEqual(shapes)&&current.Select(m=>m.transform.localToWorldMatrix).SequenceEqual(poses);Check(stable,"pose/mesh invariant across save");Check(root.GetComponentsInChildren<Collider>().Length==0,"noncollision");bool noDouble=true;foreach(var renderer in root.GetComponentsInChildren<Renderer>()){var block=new MaterialPropertyBlock();renderer.GetPropertyBlock(block);noDouble&=block.isEmpty;}Check(noDouble,"saved blocks empty");
  rows.Add(new Row{kind=kind,liveExpected=liveError<.000002f,prefabExpected=prefabError<.000002f,sceneExpected=sceneError<.000002f,oneMaterial=one,noColliders=true,poseMeshStable=stable,noDoubleTint=noDouble,instances=3,meshes=current.Select(m=>m.sharedMesh).Distinct().Count(),maxPrefabColourError=prefabError,maxSceneColourError=sceneError,liveTint=data.instances[0].tint,imageNames=images.ToArray()});}
  bool preserved=rows.All(r=>r.prefabExpected&&r.sceneExpected);bool reproduced=rows.All(r=>!r.prefabExpected&&!r.sceneExpected);File.WriteAllText(Path.Combine(Out,"checks.json"),JsonUtility.ToJson(new Report{pass=phase.StartsWith("before")?reproduced:preserved,phase=phase,regressionPassed=preserved,lossReproduced=reproduced,rows=rows.ToArray(),limits=new[]{"Dedicated Editor only; no Player/mobile","Legacy means original vertex-colour data without optional surface; tint remains required by V1"}},true));Check(phase.StartsWith("before")?reproduced:preserved,"expected preservation regression result");Check(!ShaderUtil.ShaderHasError(Shader.Find("MapSharedProps/Lit")),"shader compile");AssetDatabase.SaveAssets();EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(Path.Combine(Out,"error.txt"),e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
 public static void RunReload(){var output=Path.Combine(Root,"Evidence180-reload");Directory.CreateDirectory(output);try{var rows=new List<Row>();foreach(var kind in new[]{"textured","legacy","badPNG"}){Empty();var data=GroundedPropsV1.Read(Path.Combine(Root,"Input180-"+kind+"/grounded_props.json"));var folder="Assets/Grounded180-after2-"+kind;var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(folder+"/cluster.prefab");Check(prefab,"saved prefab exists");var root=(GameObject)PrefabUtility.InstantiatePrefab(prefab);var expectedMaterial=AssetDatabase.LoadAssetAtPath<Material>(folder+"/grounded-shells.mat");float ep=Error(root,data);Check(ep<.000002f,"fresh Editor prefab persisted tint");Check(root.GetComponentsInChildren<Renderer>().All(x=>x.sharedMaterial==expectedMaterial),"one saved material");UnityEngine.Object.DestroyImmediate(root);EditorSceneManager.OpenScene(folder+"/reload.unity");root=GameObject.Find("tint180-root");float es=Error(root,data);var renderers=root.GetComponentsInChildren<Renderer>();Check(es<.000002f&&renderers.Length==3&&renderers.All(x=>x.sharedMaterial==expectedMaterial),"fresh Editor scene colour and sharing");foreach(var x in renderers){var b=new MaterialPropertyBlock();x.GetPropertyBlock(b);Check(b.isEmpty,"no restored double tint");}Check(root.GetComponentsInChildren<Collider>().Length==0,"noncollision persisted");rows.Add(new Row{kind=kind,prefabExpected=true,sceneExpected=true,oneMaterial=true,noColliders=true,noDoubleTint=true,instances=3,meshes=root.GetComponentsInChildren<MeshFilter>().Select(x=>x.sharedMesh).Distinct().Count(),maxPrefabColourError=ep,maxSceneColourError=es});}File.WriteAllText(Path.Combine(output,"checks.json"),JsonUtility.ToJson(new Report{pass=true,regressionPassed=true,phase="freshEditor",rows=rows.ToArray(),limits=new[]{"Dedicated Editor only; no Player"}},true));EditorApplication.Exit(0);}catch(Exception e){File.WriteAllText(Path.Combine(output,"error.txt"),e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}

}
